expect:
(() => {
  const q = window.__gc = { origin: location.origin, fetch: window.fetch.bind(window),
    next: null, gates: new Map(), previews: [], toggles: [], mutations: [], errors: [] };
  q.assert = (yes, message) => { if (!yes) throw Error(message); };
  q.until = async (predicate, milliseconds = 20000) => {
    const end = Date.now() + milliseconds;
    while (Date.now() < end) { if (predicate()) return true; await new Promise(resolve => setTimeout(resolve, 40)); }
    return false;
  };
  q.frame = () => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  q.read = async path => {
    const url = new URL(path, location.href);
    q.assert(url.origin === q.origin, 'off-origin owned read');
    const response = await q.fetch(url.href);
    q.assert(response.ok, 'owned read failed: ' + url.pathname);
    return response.json();
  };
  q.arm = (tag, mode = 'pass') => {
    q.assert(!q.next && !q.gates.has(tag) && ['pass', 'error'].includes(mode), 'invalid/reused preview gate');
    const gate = { tag, mode, ready: false, released: false };
    gate.wait = new Promise(resolve => { gate.release = resolve; });
    q.gates.set(tag, gate); q.next = gate;
  };
  q.ready = async tag => {
    const gate = q.gates.get(tag);
    q.assert(gate && await q.until(() => gate.ready), 'preview gate never answered: ' + tag);
    q.assert(q.errors.length === 0 && q.mutations.length === 0, 'fixture has an error or forbidden mutation');
    if (gate.mode === 'pass') {
      q.assert(gate.body.values.guidance_scale.includes(1) && gate.body.images === 4,
        'actual owned preview has unexpected CFG reach/count');
    }
  };
  q.release = async tag => {
    const gate = q.gates.get(tag);
    q.assert(gate?.ready && !gate.released, 'preview gate not held: ' + tag);
    gate.released = true; gate.release();
    q.assert(await q.until(() => q.toggles[gate.toggle]?.done), 'original opening handler never settled');
    q.assert(!q.toggles[gate.toggle].error, 'original handler rejected');
    await q.frame();
  };
  q.closed = () => !els.gridSection.open && gridMaxCfg === null && els.negative.disabled
    && !els.negNote.textContent.includes('for grid cells');
  q.inputs = () => JSON.stringify([els.prompt.value, els.negative.value, els.cfg.value, els.batch.value, els.runs.value,
    els.gridPrompt.value, els.gridPromptMode.value, els.gridCfg.value, els.gridSteps.value, els.seed.value]);
  q.view = () => JSON.stringify({ reach: gridMaxCfg, negative: els.negative.disabled,
    note: els.negNote.textContent, text: els.gridPreview.textContent,
    warning: els.gridPreview.classList.contains('warn'), inputs: q.inputs() });
  q.box = element => { const box = element.getBoundingClientRect(); return [box.x, box.y, box.width, box.height]; };
  // Observe completion of the exact original native-toggle handler body.
  // This wrapper adds no selection/preview logic; the summary and real event remain native.
  const originalToggle = previewGrid;
  els.gridSection.removeEventListener('toggle', originalToggle);
  els.gridSection.addEventListener('toggle', function(event) {
    const call = { open: this.open, done: false };
    q.toggles.push(call);
    const promise = originalToggle.call(this, event);
    void Promise.resolve(promise).then(() => { call.done = true; }, error => {
      call.done = true; call.error = String(error); q.errors.push(call.error);
    });
  });
  window.addEventListener('error', event => q.errors.push(String(event.message || 'window error')));
  window.addEventListener('unhandledrejection', event => q.errors.push(String(event.reason)));
  window.fetch = async (input, options) => {
    const url = new URL(typeof input === 'string' || input instanceof URL ? input : input.url, location.href);
    const method = String(options?.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase();
    if (url.origin !== q.origin) { q.mutations.push('off-origin ' + method); throw Error('off-origin request refused'); }
    if (method === 'GET' || method === 'HEAD') return q.fetch(input, options);
    if (method !== 'POST' || !['/api/grid/preview', '/api/prompt/analyze'].includes(url.pathname) || url.search) {
      q.mutations.push(method + ' ' + url.pathname); throw Error('non-preview mutation refused');
    }
    if (url.pathname !== '/api/grid/preview') return q.fetch(input, options);
    const gate = q.next; q.next = null;
    const preview = { forwarded: !gate || gate.mode === 'pass' };
    q.previews.push(preview);
    const response = preview.forwarded ? await q.fetch(input, options)
      : new Response(JSON.stringify({ detail: 'controlled obsolete grid refusal' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } });
    if (gate) {
      q.assert(q.toggles.length && q.toggles.at(-1).open, 'gate did not arise from an actual open toggle');
      gate.toggle = q.toggles.length - 1;
      gate.body = await response.clone().json(); gate.ready = true;
      await gate.wait;
    }
    return response;
  };
  return true;
})()
